window.METHODOLOGY_DATA = {"frameworks": [{"id": "bagang", "title": "八綱：陰陽、表裏、寒熱、虛實", "purpose": "整理古籍描述的性質、位置與虛實關係，作為文獻比較框架。", "dimensions": ["陰／陽", "表／裏", "寒／熱", "虛／實", "混合／疑似／未錄"], "sourceUrl": "https://zh.wikisource.org/zh-hant/景岳全書_(四庫全書本)/卷01", "quote": "隂陽旣明則表與裏對虛與實對寒與熱對明此六變明此隂陽則天下之病固不能出此八者", "limits": "出自卷一傳忠錄・明理與六變辨。『八綱』是平台對此段的整理標題，不能把四軸當互相獨立或由藥材寒熱自動推出方證；不作個人辨證。"}, {"id": "zangfu", "title": "臟腑分析：功能與相使關係", "purpose": "按古典臟腑用語整理描述與功能關係，不與現代解剖或器官藥效直接等同。", "dimensions": ["心", "肺", "肝", "脾", "腎", "膽", "胃", "大腸", "小腸", "三焦", "膀胱", "膻中／心包等版本用語"], "sourceUrl": "https://zh.wikisource.org/zh-hant/%E9%BB%84%E5%B8%9D%E5%86%85%E7%B6%93%E7%B4%A0%E5%95%8F_(%E5%9B%9B%E5%BA%AB%E5%85%A8%E6%9B%B8%E6%9C%AC)/%E5%8D%B703", "quote": "心者君主之官也神明出焉", "limits": "《素問》靈蘭秘典論、五藏別論。原文與王冰注、林億等校正須分層；此為古典功能觀，不是現代器官作用測量。不得憑『入肝』推定肝臟療效或安全。"}, {"id": "liujing", "title": "六經：六類篇章與方證脈證語境", "purpose": "比較《傷寒論》六類病脈證篇章中的方劑、條文與傳變說法。", "dimensions": ["太陽", "陽明", "少陽", "太陰", "少陰", "厥陰", "合病／並病／變證"], "sourceUrl": "https://zh.wikisource.org/zh-hant/傷寒論", "quote": "太陽之為病，脈浮，頭項強痛而惡寒。", "limits": "章節分類不等於藥物『歸經』；不得自動把六經映射為六條經脈或固定循序病程。平台只顯示原文分類，不由症狀推薦方。"}, {"id": "weiqiyingxue", "title": "衛氣營血：溫病論述層次", "purpose": "按《溫熱論》原文追蹤衛、氣、營、血等語義及變化關係。", "dimensions": ["衛", "氣", "營", "血", "逆傳／轉出／兼夾"], "sourceUrl": "https://zh.wikisource.org/zh-hant/溫熱論", "quote": "大凡看法∶衛之後方言氣，營之後方言血。", "limits": "不當作所有疾病通用的四階數值嚴重度；不把四層線性相加，也不推定必然依序傳變。篇內傳統治法僅作原文上下文，不輸出用藥指示。"}, {"id": "sanjiao", "title": "三焦：上、中、下焦的文獻定位", "purpose": "比較《溫病條辨》各焦篇章、定位及氣血津液等語境。", "dimensions": ["上焦", "中焦", "下焦", "兼及／未錄"], "sourceUrl": "https://zh.wikisource.org/wiki/溫病條辨/卷一", "quote": "二、凡病溫者，始於上焦，在手太陰。", "limits": "此為吳瑭本書論述，不宣稱所有作者一致或為實證傳染病進程。三焦和衛氣營血保留為兩套標籤，不以一套代替另一套。上焦的手太陰不能直接等同《傷寒論》的太陰病。"}, {"id": "siqi_wuwei", "title": "四氣五味：本草描述維度", "purpose": "以逐條原文建立寒熱溫涼、平、味與加工狀態資料。", "dimensions": ["寒", "涼", "平", "溫", "熱", "微／小／大等修飾詞", "酸", "苦", "甘", "辛", "鹹", "淡", "澀", "生／熟／炙等加工狀態"], "sourceUrl": "https://zh.wikisource.org/zh-hant/神農本草經", "quote": "藥有酸鹹甘苦辛五味，又有寒熱溫涼四氣及有毒無毒", "limits": "此網路轉錄版底本未明，與孫星衍輯本不是同一頁。平、微、小、大保留原文而不能說典籍提供了數值。五味並非僅感官味覺。古籍『無毒』不等於現代無風險。"}, {"id": "guijing_shengjiang", "title": "歸經與升降浮沉：方向與範圍的原文標籤", "purpose": "將特定本草條文中的所入經絡、升降浮沉及部位加工差異分別編碼。", "dimensions": ["入經／臟腑原詞", "升", "降", "浮", "沉", "可升可降／能浮能沉", "部位與加工狀態"], "sourceUrl": "https://zh.wikisource.org/zh-hant/本草備要#藥性總義", "quote": "氣味俱濃者能浮能沉，氣味俱薄者可升可降。", "limits": "總論列傳統類推規則，但不能由味或顏色自動填入每味藥的歸經／方向；只取該條明載詞，缺值保持未知。《本草備要》也指出『升降在物亦在人』，不宜給每味永久唯一方向。"}, {"id": "qiqing", "title": "七情配伍：文獻關係分類", "purpose": "保存單行、相須、相使、相畏、相惡、相反、相殺等原文关系與出處。", "dimensions": ["單行", "相須", "相使", "相畏", "相惡", "相反", "相殺", "方向／上下文／來源"], "sourceUrl": "https://zh.wikisource.org/zh-hant/神農本草經#序", "quote": "有單行者，有相須者，有使者，有相畏者，有相惡者，有相反者，有相殺者。", "limits": "該轉錄原文寫『有使者』；標準化標籤相使須保留此異文。『相畏』不能一律等同禁用。相殺及解毒是歷史記載，不能在模型中扣減现代毒性警示。資料來源與現代注意事項分開。"}, {"id": "junchenszuoshi", "title": "君臣佐使：方內角色與解讀", "purpose": "對方劑原文或具署名的後世方解建立角色標註。", "dimensions": ["君", "臣", "佐", "使", "未載", "不同方解異說"], "sourceUrl": "https://zh.wikisource.org/zh-hant/神農本草經#序", "quote": "藥有君臣佐使，以相宣攝合和者", "limits": "同篇的上中下品之君臣佐使與方內角色不能混為固定 herb role；一味藥角色因方與方解而變。研究份數最高不自動等於君。用研究者標註時明示，不能冒稱原典。"}], "featureSchema": [{"id": "identity", "type": "record", "fields": ["herbId", "sourceName", "mappedName", "mappingStatus: exact|alias|uncertain", "botanicalIdentity", "part", "processing", "sourceId", "edition", "section", "sourceUrl", "sourceRevision", "quote", "spanStart", "spanEnd", "reviewedBy", "reviewDate"], "limits": "不同加工狀態、部位、基原分開；未核身份不填已知。exactText span 引用來源固定快照，保留繁簡字形，不可偏移到錯誤條文。"}, {"id": "thermalOrdinal", "type": "nullable_interval", "coding": {"寒": -2, "涼": -1, "平": 0, "溫": 1, "熱": 2}, "modifierCoding": {"微／小": 0.5, "大": 1.5}, "examples": [{"raw": "微寒", "value": -1}, {"raw": "微溫", "value": 0.5}, {"raw": "大熱", "value": 3}, {"raw": "生微涼／熟溫", "interval": [-0.5, 1], "status": "加工未定；非實際混合"}, {"raw": "生平／炙溫", "interval": [0, 1], "status": "加工未定"}], "limits": "這是平台公開的研究者編碼，不是古籍給出的分數、物理單位或實證藥效。序位的等距加權只是分析假設。未錄為 null，不是 0。不同來源矛盾保留各記錄，不平均成真值。"}, {"id": "tastes", "type": "multi_hot", "vocabulary": ["酸", "苦", "甘", "辛", "鹹", "淡", "澀"], "fields": ["exactSourceTerm", "sourceSpan", "normalizationMap"], "limits": "單味可能多標籤；七個詞比『五味』擴展，介面注明。binary 0 表示此來源未提及該詞，不表示確認不具該特徵。對未知保留 mask。"}, {"id": "meridians", "type": "multi_hot_plus_scope", "vocabulary": ["肝", "心", "脾", "肺", "腎", "膽", "胃", "大腸", "小腸", "膀胱", "心包", "三焦"], "fields": ["exactSourceTerm", "sourceSpan", "scopeAllTwelve", "unknownMask"], "limits": "『十二經』保留範圍詞，不視為第13條經；若展示為12個 1，明示來自全稱展開，不能當12次獨立證據。不得僅據五味類推歸經。"}, {"id": "direction", "type": "multi_hot", "vocabulary": ["升", "降", "浮", "沉"], "fields": ["exactSourceTerm", "sourceSpan", "conditionalProcessing", "conditionalPart"], "limits": "只編碼明載方向。不由性味生造方向；可升可降同時標記，不能簡化為零。"}, {"id": "lexicalActions", "type": "multi_hot_with_spans", "vocabulary": "由已審核條文建立凍結詞典，例如『補氣』『燥濕』『收斂』；原詞、同義標準化與否定詞分开。", "fields": ["exactTerm", "normalizedTerm", "span", "negated", "conditional", "authorLayer"], "limits": "此為古典文本功用詞，不是測得療效。『不宜補』『非補』不可作補的正標籤。父類與子類不可在同一總分雙算。"}, {"id": "formulaRecord", "type": "record", "fields": ["formulaId", "familyId", "sourceId", "edition", "section", "herbIdentitySet", "ingredientSourceSpans", "coreIngredients", "adjunctIngredients", "labelSpans", "roleSpans", "processingMapping", "duplicateGroupId", "variantOf"], "limits": "核心成分與煎服另加材料分開。相同來源轉錄、同方異名、跨書抄錄按群去重；炮製與身份差異不應悄悄合併。"}, {"id": "riskSourceCoverage", "type": "record", "fields": ["historicalPairAlerts", "modernOfficialCautions", "toxicStatus: listed|notListedInReviewedSources|unknown", "identityUncertainty", "coverageSources", "lastReviewed"], "limits": "notListedInReviewedSources 不能命名 safe。各提示只累加，不因『相殺』、熱值抵銷、低份數或已知方身份消除。"}], "modelRecommendations": [{"id": "ordinalProfile", "spec": "w_i=r_i/sum(r); thermalInterval=[sum(w_i*L_i),sum(w_i*U_i)] 僅在所有所需項有界時可算；未知另列 coverage，不能默認0。同步展示類別分佈與正、負兩側份額，避免寒熱平均0被誤讀為平性。", "sensitivity": "基礎序位另試單調不等距編碼；微／小倍率試 0.25、0.5、0.75，大倍率試1、1.5、2。標示區間與候選排名變動，不能只公布最佳參數結果。不同假設敏感的結論標為不穩定。", "microcopy": "本平台以研究者公開編碼比較古籍標籤；分數無臨床單位，0也不能判定性平或安全。"}, {"id": "tagProfile", "spec": "分開輸出 raw multi-hot presence 與按研究份數加權標籤分布。用 sum(w_i*v_ik/k_i) 可使各維度各自100%；或者 sum(w_i*v_ik) 表示涵蓋權重但总和可能超100%，兩種不可混稱。未知 mask 保留；十二經范围另列。", "limits": "不能跨溫度、味、歸經、功用直接加總，尺度與詞數不同；歸經不能當藥物遞送概率。"}, {"id": "knownFormulaConcordance", "spec": "以獨立標註的方劑原文方義詞為 comparison labels，模型只從 herb attributes 聚合推導 lexical profile；評估 macro precision/recall、label-ranking、逐方不符合項與來源覆蓋率。這是文獻一致性。方名、方義摘要不得進入 input features。", "limits": "如果方劑標籤和模型屬性都由同一規則產生，結果只算內部一致性，不算驗證。獨立方解的傳統判斷也不是實證藥理或療效。"}, {"id": "pairCorpusStatistics", "spec": "對 N 個去重且有明確成分的方劑群，A/B 是否出現為binary；n11=A與B，n10=A無B，n01=B無A，n00=兩者皆無，N=四格總和。每方對同一味只計一次；N 必須含兩者皆無的方，不能只取含A或B的方。", "phi": "令 a=n11+alpha,b=n10+alpha,c=n01+alpha,d=n00+alpha,alpha=0.5。phi=(a*d-b*c)/sqrt((a+b)*(c+d)*(a+c)*(b+d))。原始邊際若為0或N不得定，顯示無法估計，不靠平滑捏造關係。", "logLift": "N'=N+4*alpha；logLift=ln((a/N')/(((a+b)/N')*((a+c)/N')))；所有概率來自同一平滑2x2表，避免不同分母。保留原始四格與 alpha。", "uncertainty": "小語料只顯頻數。可预先指定 N<30、n11<3 或任一邊際<3為樣本不足（研究者展示規則，不是充分證據門檻）。以方族 cluster bootstrap 看稳定性；探索多對藥材需校正多重比較；phi/loglift 表示 corpus association，絕不稱協同藥效。", "example": {"N": 100, "n11": 20, "n10": 10, "n01": 20, "n00": 50, "unsmoothedPhi": 0.3563483225498992, "unsmoothedLogLift": 0.5108256237659907, "meaning": "同現相對此語料較多；不證明有效、安全或因果。"}}, {"id": "candidateGeneration", "spec": "只從已核對已知方的 herb identity pools 生成有限組合；每個候選保留母方來源，3至6味與1至3抽象份數可作預先固定探索設定。目標是指定古典詞／分佈，例如『甘味標籤涵蓋高、入脾原詞、溫類分佈』，不接受症狀／疾病療效目標。", "objective": "公開多目標／Pareto：lexicalProfileAlignment；sourceCoverage；identityCertainty；novelty=1-maxJaccard(候選,已知方)；候選間 diversity=1-Jaccard；complexity penalty。不得宣稱所有目標有同一自然權重。展示參數與可替代候選，不給單一最佳處方。", "constraints": "排除已錄毒性及未定加工/基原身份；排除已命中的歷史相反或官方注意 pairs；每味及每个目標特徵必須有可查 source span。詞彙匹配分數不能抵銷約束。這只通過指定資料約束，不是通過安全驗證。", "output": "標題『待審文獻組合假設』。展示成分名、抽象研究份數、命中詞、已知方重疊、來源、未知與約束。無克數、製備、服用法、療效/安全分數。僅供文獻研究，尚無臨床或實驗有效性證據。"}], "validationProtocol": [{"id": "freezeCorpus", "step": "在開發前凍結來源修訂版與校訂記錄；建立公式身份、版本與抄錄 genealogy。先按 duplicateGroupId/familyId 分組，再切分；跨訓練與測試不得出現同方異名、同成分重抄、加減近親方。"}, {"id": "independentAnnotation", "step": "两名審核者用原典逐味摘取 exact spans，第三者處理異議；方義 labels 由另一標註流獨立從方劑正文／指定方解摘取，標註者不看模型輸出。建立 test gold 前不查看模型錯誤來調標籤。"}, {"id": "split", "step": "先以方族分組切 training/development/test；樣本足夠時可70/15/15，比例只是設計選擇。另做按作者／年代／典籍 leave-one-source-out 外部測試。屬性詞典、熱性編碼、詞彙映射及所有權重只在 training/development 選定，test 最後用一次。"}, {"id": "smallCorpus", "step": "目前4方不足以估計泛化或配伍相關；最多做資料與算法演示。若方族少，用 group leave-one-out 並披露每折結果、無法估計項；仍不稱獨立實證。擴大語料與標註前候選不以『統計證實』排序。"}, {"id": "baselines", "step": "比較頻率先驗、成分數匹配的隨機組合、簡單不加權標籤聚合。做熱值／味／歸經／詞彙的獨立消融；報出較基線提升與不確定性，不能只展示經方成功案例。"}, {"id": "negativeControls", "step": "打亂 training 方義 labels（以來源／方族為單位）、替換未見 herb 及加工狀態，檢查性能是否降至基線；反例包括相似成分但不同原方義、未知性味、矛盾來源、混合加工、相反藥對。"}, {"id": "noLeakage", "step": "預先定義 input 不含方名、正文方義、測試標籤、方劑類別或其同義詞。從同一條文同时取屬性與標籤的情況，明示共同來源依赖並另用不同典籍 source holdout。不要把模型產生的 labels 當 gold。"}, {"id": "metrics", "step": "資料層評估來源摘錄正確率、映射錯誤率、missing coverage和 inter-rater agreement；模型層評估獨立方義詞 macro F1/PR與排名、逐方誤差；統計層按去重方族 bootstrap，不按鏡像轉錄本抽樣。對樣本不足的類別報NA，拒絕0/100的假精度。"}, {"id": "candidateReview", "step": "候選生成只用training池；凍結後由不知生成參數的審核者依預定文獻一致性 rubric檢查詞義、身份、來源、限制及 novelty；引用率高不等於安全。候選不得被回填語料造成循環證明，收錄需標生成而非歷史方。"}, {"id": "successBoundary", "step": "驗證能支持『摘錄可靠、編碼可復算、對未見古籍方義有描述一致性』；不能支持人體效力、毒理、交互作用、安全、診斷或實際劑量。臨床／實驗驗證是另一研究，不能由以上數據替代。"}], "sourceVerification": {"verifiedAt": "2026-10-04", "method": "web open 顯示正文，核對所引段。", "notes": ["素問來源的實際頁名含『黄帝内經』混合字形；保留工具返回的已驗證URL，不使用猜測的全繁體頁名。", "溫病條辨卷一的實際子頁為 /wiki/溫病條辨/卷一；『卷一·上焦篇』是頁內顯示名，不能据此猜URL。", "神農本草經此頁未標明底本；僅注明網路轉錄版，不能直接標孫星衍輯本。", "本草綱目序例上未檢得所需原文，未用其作升降浮沉來源；改用本草備要藥性總義。"]}};
